# File-type badges: the file outline with a short label; the label text is part of the icon, not colour alone.
FILE_TYPES = {"docx": "W", "doc": "W", "odt": "T", "xlsx": "X", "xls": "X", "ods": "S", "pdf": "PDF", "kicad_sch": "SCH", "kicad_pcb": "PCB",
              "fcstd": "CAD", "step": "CAD", "md": "MD", "txt": "TXT", "csv": "CSV", "png": "IMG", "jpg": "IMG", "jpeg": "IMG", "svg": "IMG",
              "json": "{ }", "eml": "@"}

# Which icon stands for a record type (anything missing gets "file").
TYPE_ICONS = {"bill": "coins", "purchase-request": "cart", "purchase-order": "clipboard", "receipt": "truck", "ncr": "alert", "capa": "retry",
              "audit": "clipboard", "calibration": "sliders", "complaint": "message", "management-review": "users", "training": "award",
              "change-request": "workflow", "supplier-evaluation": "star", "design": "tool", "requirement": "flag", "part": "box", "item": "box",
              "document": "file-text", "task": "check-circle", "journal": "book", "journal-reversal": "retry", "asset": "cpu"}


def icon(name: str, label: str | None = None, cls: str = "") -> str:
    """One inline SVG. Decorative (aria-hidden) unless ``label`` names it for assistive technology."""
    body = ICONS.get(name) or ICONS["file"]
    a11y = f' role="img" aria-label="{esc(label)}"' if label else ' aria-hidden="true"'
    c = f' class="i{(" " + cls) if cls else ""}"'
    return (f'<svg{c} width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" '
            f'stroke-linecap="round" stroke-linejoin="round" focusable="false"{a11y}>{body}</svg>')


def file_icon(filename: str | None, label: bool = True, cls: str = "ftype") -> str:
    """A file badge for a document by its extension: the file outline with the type's letters inside."""
    ext = (filename or "").rsplit(".", 1)[-1].lower() if filename and "." in filename else ""
    text = FILE_TYPES.get(ext, ext[:4].upper() or "FILE")
    a11y = f' role="img" aria-label="{esc(ext or "file")}"' if label else ' aria-hidden="true"'
    return (f'<svg class="i {cls} ft-{esc(ext or "file")}" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" '
            f'stroke-linecap="round" stroke-linejoin="round" focusable="false"{a11y}>'
            f'<path d="M13 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><polyline points="13 2 13 9 20 9"/>'
            f'<text x="12" y="18.5" text-anchor="middle" stroke="none" fill="currentColor" style="font:700 6px system-ui,sans-serif">{esc(text)}</text></svg>')


def type_icon(record_type: str | None, cls: str = "") -> str:
    return icon(TYPE_ICONS.get(record_type or "", "file"), cls=cls)
